export type Attempt = { attempt: number; score: number; max: number; at: string; timeSpent: number };
export type HistoryItem = {
  id: string; title: string; topic: string; session: number; assignedAt: string;
  attempts: Attempt[]; score: number; max: number; graded: boolean;
};
/** chủ điểm × tỉ lệ sai, kèm mức của tháng trước để so tiến bộ */
export type ErrorGroup = {
  topic: string; total: number; wrong: number; rate: number; prevRate: number;
  lastAt: string; trend: "tăng" | "giảm" | "ổn";
};
/** nhịp độ theo ngày — số câu đã làm và số phút ngồi làm */
export type DailyPoint = { date: string; questions: number; minutes: number };
/** bài em đã mở nhưng bỏ giữa chừng — khác hẳn "chưa mở" */
export type InProgress = {
  id: string; title: string; topic: string; openedAt: string;
  timeSpent: number; answered: number; total: number;
};
export type Profile = {
  history: HistoryItem[]; errors: ErrorGroup[];
  daily: DailyPoint[]; inProgress: InProgress[];
};

